+/**
+ * Fetch image URL from a database image ID.
+ * If the value is already a URL or data URI, returns it as-is.
+ */
+export async function getImageUrlFromId(
+  imageId: string
+): Promise<string | null> {
+  if (imageId.startsWith('http') || imageId.startsWith('data:')) {
+    return imageId;
+  }
+
+  try {
+    const response = await fetch(`/api/images/src?ids=${imageId}&format=url`);
+    if (!response.ok) {
+      return null;
+    }
+    const data = await response.json();
+    return Array.isArray(data) && data.length > 0 ? data[0] : null;
+  } catch {
+    return null;
+  }
+}
